import path from 'node:path';

const quote = JSON.stringify;
export const generatedHeader = '// Generated by BitaKit. Do not edit.';
/** Single-quoted module specifiers, matching the style of hand-written imports. */
export const specifier = (value) =>
  `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;

/**
 * The imports and type entries of one generated file. The client configuration and the server
 * file each have their own emitter, so a file's names (`entryN`, `moduleN`, `fileN`,
 * `normalizeN`) and their order depend only on what that file imports. `typedKind` decides which
 * integration kinds' type maps this file augments (the server file leaves client and both kinds
 * to the client file, which is in the same program).
 */
export function createEmitter(output, relativeTo, { typedKind = () => true } = {}) {
  const imports = [];
  let serial = 0;
  /** The next free number for a name in this file. */
  const next = () => serial++;
  const moduleSpecifier = (file) => {
    let relative = path
      .relative(output, file)
      .replaceAll(path.sep, '/')
      .replace(/\.tsx?$/, '');
    if (!relative.startsWith('.')) relative = `./${relative}`;
    return specifier(relative);
  };
  const importFile = (file, namespace = false) => {
    const name = `${namespace ? 'module' : 'entry'}${next()}`;
    imports.push(
      namespace
        ? `import * as ${name} from ${moduleSpecifier(file)};`
        : `import ${name} from ${moduleSpecifier(file)};`,
    );
    return name;
  };
  const typeMaps = () => ({
    services: [],
    actions: [],
    events: [],
    cancelable: [],
    settings: [],
    slots: [],
    configs: [],
    permissions: [],
    roles: [],
  });
  const types = typeMaps();
  /**
   * The type entries of switched-off plugins: their names stay typed (their own files and optional
   * references from other plugins still compile), but only through type-only references, so
   * nothing of them reaches the bundle. A name an enabled module holds wins (see `withoutEnabled`).
   */
  const switchedOff = typeMaps();
  /** One `fileN = discoveredFile(entryN, path, source)` per entry; returns the `fileN` names. */
  const fileEntries = (entries) =>
    entries.map((entry) => {
      const imported = importFile(entry.file);
      const name = `file${next()}`;
      imports.push(
        `const ${name} = discoveredFile(${imported}, ${quote(entry.path.join('.'))}, ${quote(relativeTo(entry.file))});`,
      );
      return name;
    });
  /**
   * One type-only `TypeFileN = DiscoveredFile<typeof import(…).default, path>` per entry: the same
   * shape `fileN` has, without importing the file. Returns the `TypeFileN` names.
   */
  const typeFileEntries = (entries) =>
    entries.map((entry) => {
      const name = `TypeFile${next()}`;
      imports.push(
        `type ${name} = DiscoveredFile<typeof import(${moduleSpecifier(entry.file)}).default, ${quote(entry.path.join('.'))}>;`,
      );
      return name;
    });
  /** Records the type entries of a built-in kind's files (`refs`: `typeof fileN` or `TypeFileN`). */
  const record = (into, kind, refs, moduleId) => {
    if (kind === 'actions')
      for (const ref of refs)
        into.actions.push(`DiscoveredActionEntry<${ref}, ${quote(moduleId)}>`);
    if (kind === 'services')
      for (const ref of refs)
        into.services.push(`DiscoveredServiceEntry<${ref}, ${quote(moduleId)}>`);
    if (kind === 'events')
      for (const ref of refs) {
        into.events.push(`DiscoveredEventsEntry<${ref}, ${quote(moduleId)}>`);
        into.cancelable.push(`DiscoveredCancelableEntry<${ref}, ${quote(moduleId)}>`);
      }
    if (kind === 'settings')
      for (const ref of refs)
        into.settings.push(`DiscoveredSettingsEntry<${ref}, ${quote(moduleId)}>`);
    if (kind === 'slotDefinitions')
      for (const ref of refs) into.slots.push(`DiscoveredSlotEntry<${ref}, ${quote(moduleId)}>`);
    if (kind === 'configs')
      into.configs.push(
        `${quote(moduleId)}: ${refs.map((ref) => `DiscoveredConfigEntry<${ref}>`).join(' & ') || '{}'};`,
      );
  };
  /** The type entries of a switched-off plugin's files of a built-in kind; nothing at runtime. */
  const emitTypes = (kind, entries, moduleId) =>
    record(switchedOff, kind, typeFileEntries(entries), moduleId);
  /** The type entries of a switched-off plugin's `permissions.ts`; nothing at runtime. */
  const permissionTypes = (file) =>
    switchedOff.permissions.push(`PermissionsOf<typeof import(${moduleSpecifier(file)}).default>`);
  /**
   * A switched-off map without the names an enabled map already holds (`enabled`: type names),
   * so an alias, explicit ID or resource both claim stays the enabled module's alone.
   */
  const withoutEnabled = (entries, enabled) =>
    entries.length
      ? `Omit<${entries.join(' & ')}, ${enabled.map((name) => `keyof ${name}`).join(' | ')}>`
      : '{}';
  /** The `discover*` call of a built-in kind; records the file's type entries. */
  const emit = (kind, entries, moduleId) => {
    const names = fileEntries(entries);
    record(
      types,
      kind,
      names.map((name) => `typeof ${name}`),
      moduleId,
    );
    const fn = {
      actions: 'discoverActions',
      services: 'discoverServices',
      slotDefinitions: 'discoverSlots',
      interceptors: 'discoverInterceptors',
      installers: 'discoverInstallers',
      configs: 'discoverConfig',
      events: 'discoverEvents',
      settings: 'discoverSettings',
    }[kind];
    const extra =
      kind === 'actions' || kind === 'services' || kind === 'slotDefinitions'
        ? `, ${quote(moduleId)}`
        : '';
    return `${fn}([${names.join(', ')}]${extra})`;
  };
  const normalizers = new Map();
  /** Integration kinds with a type map, by name: `{ kind, index, entries }`. */
  const kindTypes = new Map();
  /**
   * A module's `contributions` object: `entriesByKind[index]` holds the files of `kinds[index]`.
   * Names use the kind's index, so they stay stable while other kinds come and go.
   */
  const contributions = (kinds, entriesByKind, moduleId) => {
    const parts = [];
    kinds.forEach((kind, index) => {
      const entries = entriesByKind[index];
      if (!entries.length) return;
      if (!normalizers.has(kind.name)) {
        const alias = `normalize${index}`;
        imports.push(`import { ${kind.normalize} as ${alias} } from ${specifier(kind.from)};`);
        normalizers.set(kind.name, alias);
      }
      const names = fileEntries(entries);
      if (kind.types && typedKind(kind)) {
        if (!kindTypes.has(kind.name)) {
          imports.push(
            `import type { ${kind.types.entry} as KindEntry${index} } from ${specifier(kind.from)};`,
          );
          kindTypes.set(kind.name, { kind, index, entries: [] });
        }
        kindTypes
          .get(kind.name)
          .entries.push(
            ...names.map((name) => `KindEntry${index}<typeof ${name}, ${quote(moduleId)}>`),
          );
      }
      parts.push(
        `${quote(kind.name)}: ${normalizers.get(kind.name)}([${names.join(', ')}], ${quote(moduleId)})`,
      );
    });
    return `{ ${parts.join(', ')} }`;
  };
  /** `declare module '<from>'` augmentations of the integration kinds' type maps. */
  const kindDeclarations = () =>
    [...kindTypes.values()]
      .map(
        ({ kind, index, entries }) =>
          `type KindMap${index} = ${entries.join(' & ')};\ndeclare module ${specifier(kind.from)} { interface ${kind.types.map} extends KindMap${index} {} }`,
      )
      .join('\n');
  return {
    imports,
    types,
    switchedOff,
    next,
    importFile,
    fileEntries,
    typeFileEntries,
    emit,
    emitTypes,
    permissionTypes,
    withoutEnabled,
    contributions,
    kindDeclarations,
  };
}
